SALES_FUNDS_UI.syncField=(d,editable)=>{const el=document.querySelector('[data-funds-field]');if(!el)return;if(el.contains(document.activeElement)){for(const select of el.querySelectorAll('select[data-rf=accountId]')){const i=Number(select.closest('[data-funds-row]').dataset.fundsRow),f=d.fundsRecords?.[i]||{methodId:'',accountId:''},next=document.createElement('select');next.innerHTML=`<option value="" disabled hidden ${f.accountId?'':'selected'}>资金账户</option>${accountOptions(d,f)}`;if(select.innerHTML!==next.innerHTML){select.innerHTML=next.innerHTML;select.value=f.accountId||'';UNIFIED_SINGLE_SELECT?.mountAll?.()}}const balance=el.querySelector('[data-funds-balance]'),status=paymentStatus(d);if(balance){balance.textContent=status.text;balance.className='sale-payment-balance '+status.kind}const virtual=el.querySelector('[data-funds-row="0"] [data-rf="amount"]');if(virtual&&!(d.fundsRecords||[]).length&&virtual!==document.activeElement)virtual.value=SALES_CORE.money(dueAmount(d));const add=el.querySelector('[data-rf-add]');if(add){add.disabled=!canAddPayment(d);add.title=add.disabled?'请先填写有效收款金额':''}return}el.outerHTML=fundsField(d,editable);UNIFIED_SINGLE_SELECT?.mountAll?.()};
SALES_FUNDS_UI.remember=()=>{};
SALES_FUNDS_UI.validate=(d,{audit=false}={})=>{const rows=d.fundsRecords||[];for(const f of rows){const m=fundMethods().find(x=>x.id===f.methodId),a=availableAccounts(d,f.methodId).find(x=>x.id===f.accountId);if(!m||m.enabled===false||!a)return '请选择正常收款方式及可用的资金账户';if(!Number.isSafeInteger(f.amountCents))return '请填写有效收款金额'}if(audit&&fundsSum(d)!==dueAmount(d))return '收款合计与应结金额不一致，请核对后再审核';return ''};
document.addEventListener('change',e=>{const row=e.target.closest('[data-funds-row]');if(!row||!e.target.dataset.rf||!SALES_UI.state.editing)return;const d=SALES_UI.state.doc,i=Number(row.dataset.fundsRow),f=d.fundsRecords[i]||{id:crypto.randomUUID(),methodId:'',accountId:'',amountCents:dueAmount(d)-fundsSum(d)};if(!d.fundsRecords[i])d.fundsRecords.push(f);if(e.target.dataset.rf==='methodId'){f.methodId=e.target.value;const choices=availableAccounts(d,f.methodId);f.accountId=choices.length===1?choices[0].id:''}else if(e.target.dataset.rf==='accountId')f.accountId=e.target.value;else return;SALES_UI.update();rerenderFunds(e.target.dataset.rf==='methodId'?'accountId':'amount',i)});
document.addEventListener('input',e=>{const row=e.target.closest('[data-funds-row]');if(!row||e.target.dataset.rf!=='amount'||!SALES_UI.state.editing)return;const d=SALES_UI.state.doc,i=Number(row.dataset.fundsRow),f=d.fundsRecords[i]||{id:crypto.randomUUID(),methodId:'',accountId:'',amountCents:0};if(!d.fundsRecords[i])d.fundsRecords.push(f);const raw=e.target.value.trim(),negative=raw.startsWith('-'),value=SALES_CORE.cents(negative?raw.slice(1):raw);f.amountRaw=e.target.value;f.amountCents=value==null?null:value*(negative?-1:1);SALES_UI.update()});
document.addEventListener('focusout',e=>{if(e.target.dataset.rf!=='amount')return;const d=SALES_UI.state.doc,f=d?.fundsRecords?.[Number(e.target.closest('[data-funds-row]')?.dataset.fundsRow)];if(f&&Number.isSafeInteger(f.amountCents)){delete f.amountRaw;e.target.value=SALES_CORE.money(f.amountCents)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-rf-add],[data-rf-remove]');if(!el||!SALES_UI.state.editing)return;const d=SALES_UI.state.doc;if(el.hasAttribute('data-rf-add')){if(!canAddPayment(d))return;const due=dueAmount(d),remaining=due-fundsSum(d),amount=due<0?Math.min(0,remaining):Math.max(0,remaining);d.fundsRecords.push({id:crypto.randomUUID(),methodId:'',accountId:'',amountCents:remaining===0?null:amount,direction:due<0?'refund':'receipt'});SALES_UI.update();rerenderFunds('methodId')}else{d.fundsRecords.splice(Number(el.dataset.rfRemove),1);SALES_UI.update();rerenderFunds('methodId')}});
bridge.inventory=async(query,page=1,size=200)=>{const match=new Set(INVENTORY_RESULT.search(query.keyword||'','normal').map(p=>p.id));const selected=D.products.filter(p=>(query.products.length?query.products.includes(p.id):!query.keyword||match.has(p.id))&&INVENTORY_RESULT.matchesCategory(p,query)&&Object.entries(query.more||{}).every(([key,value])=>(Array.isArray(value)?value:[value]).some(v=>key==='season'?C.seasonValues(p).includes(String(v)):key==='fitId'&&v==='__unset'?!C.fits2026.some(f=>f.id===p.fitId):String(p[key])===String(v))));
 const r=await api('/runtime/inventory?page='+page+'&size='+size+'&unit=product',{products:selected.map(p=>p.id),warehouses:query.warehouses});const products=selected.filter(p=>r.rows.some(x=>x.code===p.id)),groups=new Map();
 const rows=r.rows.map(x=>{const p=products.find(p=>p.id===x.code),c=p.colorIds.indexOf(x.color_id),w=D.warehouses.find(w=>w.id===x.warehouse_id);return {key:JSON.stringify([p.id,x.color_id,w.id]),p:p.id,c,color:p.colors[c],w:w.id,warehouse:w.name,warehouseCode:w.code,values:p.sizeIds.map(s=>Object.hasOwn(x.values,s)?Number(x.values[s]):p.skuByCell[x.color_id+'|'+s]?0:null),total:Number(x.total),index:Number(x.index)};});
 for(const g of [...(r.products||[]),...(r.colors||[])]){const p=products.find(x=>x.id===g.code),cols=p.sizeIds.map(id=>Number(g.cols[id]||0)),key=g.color_id?g.code+'|'+p.colorIds.indexOf(g.color_id):g.code;groups.set(key,{cols,total:cols.reduce((a,b)=>a+b,0),first:Number(g.first),last:Number(g.last)});}
 return {remote:true,query:copy(query),products,productCount:Number(r.productCount),warehouses:D.warehouses.filter(w=>query.warehouses.includes(w.id)),rows,rowCount:Number(r.rowCount),groups,total:Number(r.total),negative:0,unknown:0,created:new Date().toISOString()};};
const resultPage=INVENTORY_RESULT.page;INVENTORY_RESULT.page=(snap,page,size)=>snap.remote?snap.rows:resultPage(snap,page,size);
bridge.allInventory=async()=>{const W=INVENTORY_UI.state,previous=W.snapshot;if(!previous?.remote)return ()=>{};const snapshots=[];for(let page=1;page<=Math.ceil(previous.productCount/500);page++)snapshots.push(await bridge.inventory(previous.query,page,500));const products=[...new Map(snapshots.flatMap(s=>s.products).map(p=>[p.id,p])).values()];await stock(products.map(p=>p.id));W.snapshot={...previous,products,rows:snapshots.flatMap(s=>s.rows),groups:new Map(snapshots.flatMap(s=>[...s.groups]))};return ()=>{W.snapshot=previous;};};

